//! L11 太虚幻境系统目录：效果类型、`effectPack`、`buffPack`、`cardRank`、侍灵动作与六阶技能表。

/// 太虚幻境事件/战利品原子效果种类（对应 `extension_framework.js:4751-5424` `moveEffect`）。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaixuEffectKind {
    Coin, Exp, Hp, MaxHp, MinHs, MaxHs, Adjust, MaxSkills,
    Card, RandomCard, Basic, Trick, RemoveCard,
    Equip, RandomEquip, Equip1, Equip2, Equip5, RandomUnique, RemoveEquip,
    Buff, RandomBuff, RemoveBuff,
    Skill, RandomSkill, Attack, Defense, Assist, Burst, RemoveSkill,
}

/// 单条原子效果规格。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TaixuEffectSpec {
    pub kind: TaixuEffectKind,
    pub number: i32,
    pub result: &'static str,
}
impl TaixuEffectSpec {
    pub const fn new(kind: TaixuEffectKind, number: i32, result: &'static str) -> Self {
        Self { kind, number, result }
    }
}

/// 卡牌分类（用于商店筛选与随机牌/装备分类）。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaixuCardCategory {
    Basic, Trick, Delay, Equip1, Equip2, Equip3, Equip4, Equip5, Equip6,
}
impl TaixuCardCategory {
    pub const fn is_equip(self) -> bool {
        matches!(self, Self::Equip1 | Self::Equip2 | Self::Equip3 | Self::Equip4 | Self::Equip5 | Self::Equip6)
    }
    pub const fn equip_slot_name(self) -> Option<&'static str> {
        match self {
            Self::Equip1 => Some("equip1"), Self::Equip2 => Some("equip2"),
            Self::Equip3 => Some("equip3"), Self::Equip4 => Some("equip4"),
            Self::Equip5 => Some("equip5"), Self::Equip6 => Some("equip6"),
            _ => None,
        }
    }
}

/// 1..=10 级升级经验阈值（`extension_framework.js:4784-4800,9396-9412`）。
pub const L11_TAIXU_LEVEL_XP_THRESHOLDS: [u32; 10] = [0, 100, 300, 700, 1200, 1800, 2300, 3000, 3500, 4000];

pub const fn taixu_max_exp_for_level(level: u8) -> u32 {
    match level {
        0 | 1 => 100, 2 => 300, 3 => 700, 4 => 1200, 5 => 1800,
        6 => 2300, 7 => 3000, 8 => 3500, _ => 4000,
    }
}

